import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';
import {services, industries} from '../content/services.mjs';
import {guides as preparedGuides} from '../content/guides.mjs';
import {loadGenerated} from './editorial.mjs';
const guides=[...preparedGuides,...loadGenerated().map(g=>({...g,sectionSources:g.sections.map(s=>s.sourceIndexes),sections:g.sections.map(s=>[s.heading,s.body])}))];

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const today=process.env.BUILD_DATE || new Date().toISOString().slice(0,10);
if(!/^\d{4}-\d{2}-\d{2}$/.test(today)||Number.isNaN(Date.parse(today))) throw Error('Invalid BUILD_DATE');
const origin='https://dreamprotocol.ai';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=s=>JSON.stringify(s).replace(/</g,'\\u003c');
const read=f=>fs.readFileSync(path.join(root,f),'utf8');
const write=(f,s)=>{fs.mkdirSync(path.dirname(path.join(root,f)),{recursive:true});fs.writeFileSync(path.join(root,f),s);};
const hash=f=>createHash('sha256').update(read(f)).digest('hex').slice(0,10);
const version=hash('assets/site.css');
const uiVersion=hash('assets/site.js');
const appVersion=hash('app.js');
const pages=[];
const published=guides.filter(g=>g.status==='scheduled'&&g.publishOn<=today).sort((a,b)=>b.publishOn.localeCompare(a.publishOn)||a.slug.localeCompare(b.slug));
for(const g of guides){
 if(!/^[a-z0-9-]+$/.test(g.slug)||!/^\d{4}-\d{2}-\d{2}$/.test(g.publishOn))throw Error('Invalid guide path/date');
 if(g.status==='scheduled'&&(!g.description||g.sections.length<3||!services.some(s=>s.slug===g.service)))throw Error('Incomplete scheduled guide: '+g.slug);
}
const href=slug=>{const [pathname,query]=slug.split('?');return '/'+(pathname?pathname+'/':'')+(query?'?'+query:'');};
const link=(slug,label,cls='')=>`<a${cls?` class="${cls}"`:''} href="${href(slug)}">${esc(label)}</a>`;
const button=(slug,label='Let’s talk',secondary=false)=>link(slug,label+' ↗','button'+(secondary?' secondary':''));
const eyebrow=s=>`<p class="eyebrow">${esc(s)}</p>`;
const heading=(k,h,p='')=>`<div class="section-heading">${eyebrow(k)}<h2>${h}</h2>${p?`<p>${esc(p)}</p>`:''}</div>`;
const org={'@type':'Organization','@id':origin+'/#organization',name:'Dream Protocol',legalName:'Dream Protocol',url:origin+'/',email:'hello@dreamprotocol.ai',logo:origin+'/favicon.svg',description:'AI business automation, voice agents, AI workflow automation, and AI integrations for Bay Area businesses.',slogan:'Business, evolved.',founder:{'@type':'Person',name:'Dustin Poole'},areaServed:{'@type':'Place',name:'San Francisco Bay Area'},contactPoint:[{'@type':'ContactPoint',email:'hello@dreamprotocol.ai',contactType:'sales',areaServed:'US',availableLanguage:'English'}],knowsAbout:['AI business automation','AI voice agents','AI workflow automation','AI integrations','AI knowledge agents','APIs','Microsoft 365','CRM integration']};
function nav(active=''){
 return `<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="shell nav-wrap"><a class="brand" href="/" aria-label="Dream Protocol home"><span class="brand-mark" aria-hidden="true"></span><span>dream<span class="brand-light">protocol</span><small>BUSINESS, EVOLVED.</small></span></a><button class="menu-button" type="button" aria-expanded="false" aria-controls="primary-nav"><span class="sr-only">Open menu</span><span></span><span></span></button><nav id="primary-nav" aria-label="Primary navigation">${[['services','Services'],['industries','Industries'],['bay-area-ai-services','Bay Area'],['resources','Resources'],['pricing','Pricing'],['about','About']].map(([s,l])=>`<a href="/${s}/"${active===s?' aria-current="page"':''}>${l}</a>`).join('')}</nav><div class="nav-status" aria-hidden="true"><i></i><span>AI ONLINE</span></div>${button('contact','Automate something')}</div></header>`;
}
function footer(){return `<footer><div class="footer-glow" aria-hidden="true"></div><div class="shell"><div class="footer-command"><span><i></i>DREAMPROTOCOL SYSTEM</span><b>BUSINESS, EVOLVED.</b><span>AI / VOICE / AUTOMATION / INTEGRATION</span></div><div class="footer-top"><a class="brand" href="/"><span class="brand-mark" aria-hidden="true"></span>dream<span class="brand-light">protocol</span></a><p>Your business.<br><em>Running smarter.</em></p><a class="email-link" href="mailto:hello@dreamprotocol.ai">hello@dreamprotocol.ai ↗</a></div><div class="footer-columns"><div><h2>What we do</h2>${flagshipServices.map(s=>link(s.slug,s.name)).join('')}${link('services','All services →')}</div><div><h2>Your business</h2>${industries.map(s=>link(s.slug,s.name)).join('')}</div><div><h2>Explore</h2>${[['bay-area-ai-services','Serving the Bay Area'],['pricing','Scope & pricing'],['resources','Guides & insights'],['about','About Dream Protocol'],['security','Security & data'],['contact','Start automating']].map(([s,l])=>link(s,l)).join('')}</div><div><h2>System status</h2><p class="footer-live"><i></i> Ready to build</p><p>San Francisco Bay Area<br>Remote + onsite projects</p></div></div><div class="footer-bottom"><span>© ${today.slice(0,4)} Dream Protocol</span><span>YOUR BUSINESS → DREAM PROTOCOL → DONE</span><a href="/resources/feed.xml">RSS feed ↗</a></div></div></footer>`;}
function cta(){return `<section class="cta-band"><div class="cta-grid" aria-hidden="true"></div><div class="shell"><div>${eyebrow('READY WHEN YOU ARE')}<h2>Give AI one job.<br><em>Make it earn the next one.</em></h2><p>Start with one place where customers wait, leads go cold, or your team repeats the same work. We will map the AI, the actions it can take, and the human fallback.</p></div><div class="cta-actions">${button('contact','Find my first AI workflow')}<a class="text-link" href="/#demo">Try the live AI demo ↗</a></div></div></section>`;}

const protocolBar=()=>`<div class="protocol-bar" aria-hidden="true"><div class="shell"><span>AI BUSINESS AUTOMATION</span><span class="protocol-live"><i></i>SYSTEM ONLINE</span><span>VOICE · LEADS · SCHEDULING · WORKFLOWS · DOCUMENTS · KNOWLEDGE</span></div></div>`;
const stackSection=()=>`<section class="section stack-section"><div class="shell">${heading('AI THAT WORKS WITH THE TOOLS YOU ALREADY HAVE','The model is only the brain.<br><em>The connections make it useful.</em>','Dream Protocol combines AI models, voice, business software, APIs, and automation so an agent can understand a request and take the next approved action.')}<div class="stack-grid">${['OpenAI / model APIs','Vapi / voice AI','Microsoft 365 / Graph','Google Workspace','Salesforce & CRM platforms','QuickBooks & accounting','Python / REST APIs','Webhooks & business systems','Calendars & scheduling','Business phone systems','SharePoint / OneDrive','Custom AI integrations'].map((x,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><strong>${x}</strong></div>`).join('')}</div><p class="section-note">The exact stack depends on your workflow. We confirm API access, permissions, licensing, data handling, and the actions the AI is allowed to take before launch.</p></div></section>`;

const outcomesSection=()=>`<section class="section shell outcomes-section">${heading('MEASURE THE BUSINESS RESULT','If it works, you should<br><em>be able to see it.</em>','We define the operational metric before launch so the automation has something more useful than “AI is cool” to prove.')}<div class="outcome-grid">${[['Response time','How quickly a caller, lead, or request gets a useful first response.'],['Missed opportunities','Calls, leads, bookings, or follow-ups that no longer disappear into a queue.'],['Admin time','Repeated typing, routing, searching, and status work removed from the team.'],['Cycle time','How long a quote, document, request, booking, or handoff takes to reach the next step.'],['Exception rate','How often the system needs human rescue and where the workflow needs tuning.'],['Adoption','Whether the people using the system actually trust it enough to keep using it.']].map(([h,p],i)=>`<article><span>0${i+1}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section>`;
const popularAutomationSection=()=>`<section class="section pale-section popular-automation"><div class="shell">${heading('WHAT COMPANIES KEEP ASKING FOR','The repeated work<br><em>worth attacking first.</em>','These are common starting points because they are easy to recognize, measurable, and tied directly to revenue or staff time.')}<div class="popular-grid">${[['Missed-call recovery','Answer after hours, capture context, route urgency, and trigger follow-up.'],['Lead response & nurture','Respond fast, qualify, follow up, update CRM, and alert sales.'],['Appointment booking','Check rules, request or book time, send confirmation, and handle exceptions.'],['Quote & proposal follow-up','Track sent quotes, remind customers, create tasks, and flag hot opportunities.'],['Inbox triage','Classify inbound email, extract requests, route ownership, and prepare responses.'],['Invoice & document processing','Extract data, validate fields, route low-confidence cases, and create the next record.'],['CRM updates','Turn forms, calls, email, and meetings into cleaner customer records without retyping.'],['Internal knowledge','Answer staff questions from approved policies, SOPs, manuals, and documents with source references.']].map(([h,p])=>`<article><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></div></section>`;

function layout(slug,title,description,body,{active='',schema=[],crumbs=[],home=false,article=false,noindex=false}={}){
 const url=origin+href(slug);
 const breadcrumb=crumbs.length?[{'@type':'BreadcrumbList',itemListElement:[{name:'Home',item:origin+'/'},...crumbs.map(([s,n])=>({name:n,item:origin+href(s)}))].map((x,i)=>({'@type':'ListItem',position:i+1,...x}))}]:[];
 const graph=[org,{'@type':'WebSite','@id':origin+'/#website',name:'Dream Protocol',url:origin+'/'},{'@type':'WebPage','@id':url+'#webpage',url,name:title,description,isPartOf:{'@id':origin+'/#website'},about:{'@id':origin+'/#organization'}},...breadcrumb,...schema];
 const html=`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | Dream Protocol</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${url}">${noindex?'<meta name="robots" content="noindex">':''}<meta name="theme-color" content="#101717"><meta property="og:type" content="${article?'article':'website'}"><meta property="og:title" content="${esc(title)} | Dream Protocol"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${url}"><meta property="og:image" content="${origin}/public/dream-protocol-abstract.webp"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="alternate" type="application/rss+xml" title="Dream Protocol guides" href="/resources/feed.xml"><link rel="stylesheet" href="/assets/site.css?v=${version}"><script defer src="/attribution.js"></script><script defer src="/assets/site.js?v=${uiVersion}"></script>${home?`<script>window.DREAMPROTOCOL_CONFIG={businessAnalysisEndpoint:"https://api.dreamprotocol.ai/analyze-business",vapiPublicKey:"ec40770e-0ff1-482c-929e-5288315e24b1",vapiAssistantId:"30ccf544-cd70-4ba6-8b23-fcd9ff5a4fec"};</script><script defer src="/app.js?v=${appVersion}"></script>`:''}<script type="application/ld+json">${json({'@context':'https://schema.org','@graph':graph})}</script></head>
<body data-page="${esc(slug||'home')}"${home?' data-home="true"':''}>${nav(active)}${home?'':protocolBar()}<main id="main">${body}</main>${footer()}</body></html>\n`;
 if(!noindex)pages.push({slug,url});
 write(slug?slug+'/index.html':'index.html',html);
}
const crumbs=(items)=>`<div class="shell breadcrumbs"><a href="/">Home</a>${items.map(([s,n],i)=>`<span aria-hidden="true">/</span>${i===items.length-1?`<span>${esc(n)}</span>`:link(s,n)}`).join('')}</div>`;
const serviceCard=(s,i)=>`<a href="/${s.slug}/" class="service-card service-${s.slug}" data-service="${esc(s.slug)}"><div class="service-card-visual" aria-hidden="true"><span class="service-gridline"></span><span class="service-orbit"><i></i><b>${s.icon}</b></span><span class="service-pulse"><i></i><i></i><i></i></span><small>DP / ${esc(s.name).toUpperCase()}</small></div><div class="service-card-body"><div class="card-top"><span class="card-number">${String(i+1).padStart(2,'0')}</span><span class="service-arrow" aria-hidden="true">↗</span></div><p class="eyebrow">${esc(s.tag)}</p><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><div class="card-price">${esc(s.price)} <span>${esc(s.unit)}</span></div></div></a>`;
const flagshipServices=services.slice(0,6);
const supportServices=services.slice(6);
const homeServices=['ai-front-desk','ai-lead-engine','workflow-automation'].map(slug=>services.find(s=>s.slug===slug));

const industryCards=()=>`<div class="industry-grid">${industries.map((s,i)=>`<a href="/${s.slug}/" class="industry-card"><span>0${i+1}</span><h3>${esc(s.name)}</h3><span aria-hidden="true">↗</span></a>`).join('')}</div>`;
const guideCard=g=>`<a class="guide-card" href="/resources/${g.slug}/"><div class="guide-art art-${g.service}" aria-hidden="true"><span>${services.find(s=>s.slug===g.service)?.icon||'↗'}</span></div><div class="guide-copy"><p class="eyebrow">${esc(g.category)} <span> / GUIDE</span></p><h3>${esc(g.title)}</h3><p>${esc(g.description)}</p><span class="text-link">Read the guide ↗</span></div></a>`;
const faq=items=>`<section class="shell section faq-section">${heading('A little more clarity','Questions, answered.')}<div>${items.map(([q,a])=>`<details><summary>${esc(q)}<span aria-hidden="true">+</span></summary><p>${esc(a)}</p></details>`).join('')}</div></section>`;
const processSection=()=>`<section id="implementation" class="section shell">${heading('HOW IT GOES LIVE','From friction.<br>To finished.','A direct path from the thing wasting your time to a system doing the work.')}<div class="process-grid">${[['01','Find the drag','Map the repeated work, handoffs, systems, and places your team loses time.'],['02','Design the system','Define the AI, integrations, guardrails, escalation points, and the outcome it must deliver.'],['03','Make it real','Build it, connect it, test real scenarios, and tune it against the way your business actually operates.'],['04','Keep it sharp','Measure what works, improve the weak spots, and expand only where the automation earns its keep.']].map(([n,t,p])=>`<article><span>${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section>`;
const regional=()=>`<section class="regional section"><div class="shell regional-grid"><div>${eyebrow('Built for the Bay Area')}<h2>Big possibilities.<br><em>Local understanding.</em></h2><p>From a neighborhood shop to a growing operations team. We help businesses across the San Francisco Bay Area turn AI into useful, everyday work.</p>${button('bay-area-ai-services','Explore Bay Area services',true)}</div><div class="region-visual"><span class="region-stamp">37.7749° N &nbsp; 122.4194° W</span><div class="region-orbit" aria-hidden="true"><i></i><i></i><i></i><b>DP</b></div><div class="region-names"><span>San Francisco</span><span>Peninsula</span><span>South Bay</span><span>East Bay</span><span>North Bay</span></div><small>Serving all nine Bay Area counties</small></div></div></section>`;

const architectureSection=()=>`<section class="architecture-section section"><div class="architecture-ambient" aria-hidden="true"></div><div class="shell architecture-grid"><div class="architecture-copy">${eyebrow('WHY OUR AI ACTUALLY GETS WORK DONE')}<h2>The model is not the product.<br><em>The workflow is.</em></h2><p>Useful AI has to understand the request, use the right business knowledge, work inside your CRM, calendar, inbox, phone system, or documents, then know when to hand the situation to a person. Dream Protocol designs that entire path.</p>${link('services','See the AI workflows we build ↗','text-link')}<div class="architecture-proof"><span>VOICE AI</span><span>KNOWLEDGE</span><span>CRM ACTIONS</span><span>SCHEDULING</span><span>FOLLOW-UP</span><span>HUMAN HANDOFF</span></div></div><div class="architecture-console"><div class="architecture-console-head"><span><i></i>DREAMPROTOCOL / AI ORCHESTRATION</span><b>SYSTEM ONLINE</b></div><div class="architecture-map" aria-label="Illustrative map of a production AI automation system"><div class="architecture-gridlines" aria-hidden="true"></div><div class="arch-node arch-input"><span>01</span><strong>REQUEST</strong><small>Call · form · email</small></div><div class="arch-node arch-knowledge"><span>02</span><strong>AI + KNOWLEDGE</strong><small>Intent · context · approved answers</small></div><div class="arch-node arch-systems"><span>03</span><strong>BUSINESS TOOLS</strong><small>CRM · calendar · M365</small></div><div class="arch-node arch-action"><span>04</span><strong>ACTION</strong><small>Book · update · route</small></div><div class="arch-node arch-follow"><span>05</span><strong>FOLLOW-UP</strong><small>SMS · email · task</small></div><div class="arch-node arch-human"><span>06</span><strong>HUMAN</strong><small>Exceptions · judgment</small></div><div class="arch-core"><i class="arch-ring ring-a"></i><i class="arch-ring ring-b"></i><span>DP</span><small>AI ORCHESTRATION</small></div><i class="arch-beam beam-a"></i><i class="arch-beam beam-b"></i><i class="arch-beam beam-c"></i><i class="arch-beam beam-d"></i></div><div class="architecture-ledger"><div><span>UNDERSTAND</span><b>What does this person need?</b></div><div><span>DECIDE</span><b>What approved path applies?</b></div><div><span>ACT</span><b>Take the next useful step</b></div><div><span>ESCALATE</span><b>Bring in a person when needed</b></div></div><p class="architecture-note">A chatbot stops at an answer. A production AI workflow can answer, qualify, book, update, route, follow up, and escalate through the systems your business already uses.</p></div></div></section>`;

const productionTrustSection=()=>`<section class="section production-trust"><div class="shell"><div class="section-heading split"><div>${eyebrow('AI YOU CAN TRUST WITH REAL WORK')}<h2>Fast when it should be.<br><em>Human when it matters.</em></h2></div><div><p>The goal is not to let AI do everything. The goal is to let it handle the repeatable work confidently, take only approved actions, and bring a person in when judgment or sensitivity matters.</p>${link('security','See our security & data approach ↗','text-link')}</div></div><div class="production-grid">${[['01','Knows your business','Ground answers and decisions in approved services, policies, documents, hours, and operating rules.'],['02','Takes approved actions','Define exactly what the AI may book, create, update, send, route, or request inside connected systems.'],['03','Escalates exceptions','Use confidence thresholds and clear handoffs so unusual, sensitive, or high-value situations reach a person.'],['04','Gets better over time','Review conversations and workflow outcomes, tune weak spots, and expand only when the AI is earning its keep.']].map(([n,h,p])=>`<article class="production-card"><span>${n}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></div></section>`;

const credibilitySection=()=>`<section class="section credibility-section" id="proof"><div class="shell"><div class="credibility-heading"><div>${eyebrow('WHAT DREAM PROTOCOL AI DOES')}<h2>AI that moves work.<br><em>Not just words.</em></h2></div><p>The useful version of AI does more than answer a question. It understands what is happening, uses approved business context, takes the next allowed action, and keeps a human path for everything that needs judgment.</p></div><div class="delivery-metrics" aria-label="Dream Protocol AI capabilities"><div><strong>VOICE</strong><span>answer routine calls, capture intent, and route the next step</span></div><div><strong>LEADS</strong><span>respond, qualify, follow up, and keep opportunities moving</span></div><div><strong>ACTION</strong><span>book, update, create, notify, and trigger approved workflows</span></div><div><strong>HUMAN</strong><span>escalate exceptions with the context already organized</span></div></div><div class="proof-grid proof-grid-six"><article class="proof-card proof-live"><div class="proof-status"><i></i><span>AI RECEPTION</span></div><span class="proof-number">01</span><h3>More calls become conversations</h3><p>AI can answer routine questions, capture what the caller needs, collect the details your team requires, and hand off the request cleanly.</p><div class="proof-result"><b>BUSINESS VALUE</b><span>fewer missed opportunities and less phone-tag</span></div></article><article class="proof-card"><div class="proof-status"><i></i><span>AI LEAD RESPONSE</span></div><span class="proof-number">02</span><h3>New leads get an immediate next step</h3><p>AI can respond when the inquiry arrives, ask approved qualifying questions, start follow-up, and alert a person when the opportunity is ready.</p><div class="proof-result"><b>BUSINESS VALUE</b><span>faster response and more consistent follow-up</span></div></article><article class="proof-card"><div class="proof-status"><i></i><span>AI SCHEDULING</span></div><span class="proof-number">03</span><h3>Requests move toward booked work</h3><p>AI can collect the service need, check supported rules or availability, request or book the next step, and carry clean context into dispatch.</p><div class="proof-result"><b>BUSINESS VALUE</b><span>less back-and-forth and cleaner handoffs</span></div></article><article class="proof-card"><div class="proof-status"><i></i><span>AI DOCUMENTS</span></div><span class="proof-number">04</span><h3>Documents stop becoming typing jobs</h3><p>AI can classify incoming documents, extract the fields you need, validate them, and route uncertain cases to a person before anything is committed.</p><div class="proof-result"><b>BUSINESS VALUE</b><span>less retyping and faster administrative cycles</span></div></article><article class="proof-card"><div class="proof-status"><i></i><span>AI KNOWLEDGE</span></div><span class="proof-number">05</span><h3>Your team can ask the business</h3><p>AI can answer employee questions from approved SOPs, policies, manuals, and internal documents while keeping the source visible.</p><div class="proof-result"><b>BUSINESS VALUE</b><span>faster answers without inventing policy</span></div></article><article class="proof-card"><div class="proof-status"><i></i><span>AI INTEGRATIONS</span></div><span class="proof-number">06</span><h3>The AI can work inside your tools</h3><p>Connect approved AI workflows to CRM, calendars, Microsoft 365, Google Workspace, phone systems, accounting tools, forms, and supported APIs.</p><div class="proof-result"><b>BUSINESS VALUE</b><span>AI that takes the next step instead of stopping at chat</span></div></article></div><div class="proof-scale-rail"><span><b>AI VOICE</b> customer conversations</span><span><b>AI WORKFLOWS</b> business actions</span><span><b>AI KNOWLEDGE</b> approved answers</span></div><p class="proof-disclosure">These are representative capabilities, not guarantees that every system supports every action. Production scope depends on your software, permissions, business rules, data requirements, and approved human handoffs.</p></div></section>`;

const operationsSimulatorSection=()=>`<section class="section ops-sim-section" id="operations"><div class="ops-sim-ambient" aria-hidden="true"></div><div class="shell"><div class="ops-sim-heading"><div>${eyebrow('SEE THE AI WORK / ANIMATED EXAMPLE')}<h2>Watch the work<br><em>move itself.</em></h2></div><div><p>A useful AI agent does not stop after answering. It understands intent, uses approved knowledge, applies business rules, takes the next allowed action, updates the right tool, and hands exceptions to a person.</p><div class="ops-sim-disclosure"><i></i><span>ILLUSTRATIVE WORKFLOW SIMULATION · NOT LIVE CUSTOMER TELEMETRY</span></div></div></div><div class="ops-simulator" data-ops-simulator><div class="ops-window-head"><span><i></i>DREAMPROTOCOL / OPERATIONS</span><b>SIMULATION</b><div class="ops-scene-tabs" role="tablist" aria-label="Workflow simulation"><button type="button" role="tab" aria-selected="true" data-ops-target="0">Front desk</button><button type="button" role="tab" aria-selected="false" data-ops-target="1">Lead engine</button><button type="button" role="tab" aria-selected="false" data-ops-target="2">Workflow</button></div></div><div class="ops-scenes"><article class="ops-scene is-active" data-ops-scene="0" role="tabpanel"><div class="ops-scene-copy"><span class="ops-scene-kicker">SCENE 01 / INCOMING CALL</span><h3>Caller asks.<br>Work starts moving.</h3><p>The agent listens, checks approved business context, captures intent, prepares the next action, and escalates when a person should take over.</p><div class="ops-scene-result"><b>BUSINESS RESULT</b><span>faster response · cleaner handoff · fewer missed calls</span></div></div><div class="ops-motion ops-motion-call" aria-hidden="true"><div class="ops-call-card"><span>INCOMING CALL</span><strong>New customer inquiry</strong><small>00:18</small></div><div class="ops-wave">${Array.from({length:26},(_,i)=>`<i style="--n:${i}"></i>`).join('')}</div><div class="ops-orb"><i></i><i></i><b>DP</b></div><div class="ops-transcript"><span>INTENT</span><strong>Appointment request</strong><small>Context captured · rules checked</small></div><div class="ops-motion-arrow">→</div><div class="ops-action-stack"><span class="is-on">Answer</span><span>Capture</span><span>Route</span><span>Notify</span></div></div><div class="ops-activity"><div class="ops-activity-head"><span>ACTIVITY</span><i></i></div><div class="ops-event is-hot"><span>VOICE</span><b>Call answered</b><em>now</em></div><div class="ops-event"><span>INTENT</span><b>Request understood</b><em>+2s</em></div><div class="ops-event"><span>RULES</span><b>Approved path selected</b><em>+4s</em></div><div class="ops-event"><span>TEAM</span><b>Handoff prepared</b><em>+7s</em></div></div></article><article class="ops-scene" data-ops-scene="1" role="tabpanel" hidden><div class="ops-scene-copy"><span class="ops-scene-kicker">SCENE 02 / NEW LEAD</span><h3>A form lands.<br>The next step does too.</h3><p>New inquiry arrives, useful details are extracted, qualification rules are applied, the CRM is updated, and follow-up starts without someone copying the same information three times.</p><div class="ops-scene-result"><b>BUSINESS RESULT</b><span>faster lead response · consistent follow-up · cleaner CRM</span></div></div><div class="ops-motion ops-motion-lead" aria-hidden="true"><div class="ops-lead-form"><span>NEW WEBSITE LEAD</span><i style="--w:88%"></i><i style="--w:72%"></i><i style="--w:94%"></i><i style="--w:58%"></i><strong>SUBMITTED</strong></div><div class="ops-orb"><i></i><i></i><b>DP</b></div><div class="ops-score"><span>QUALIFIED</span><strong>High intent</strong><small>service · location · timing</small></div><div class="ops-motion-arrow">→</div><div class="ops-action-stack"><span class="is-on">CRM</span><span>Follow-up</span><span>Task</span><span>Owner</span></div></div><div class="ops-activity"><div class="ops-activity-head"><span>ACTIVITY</span><i></i></div><div class="ops-event is-hot"><span>WEB</span><b>Lead captured</b><em>now</em></div><div class="ops-event"><span>AI</span><b>Context structured</b><em>+1s</em></div><div class="ops-event"><span>CRM</span><b>Record updated</b><em>+3s</em></div><div class="ops-event"><span>FOLLOW-UP</span><b>Next action created</b><em>+5s</em></div></div></article><article class="ops-scene" data-ops-scene="2" role="tabpanel" hidden><div class="ops-scene-copy"><span class="ops-scene-kicker">SCENE 03 / BUSINESS WORKFLOW</span><h3>Document in.<br>Action out.</h3><p>A document or email enters the workflow, key information is extracted, rules are checked, the destination system is updated, and low-confidence cases stay visible for human review.</p><div class="ops-scene-result"><b>BUSINESS RESULT</b><span>less retyping · faster cycle time · exceptions stay human</span></div></div><div class="ops-motion ops-motion-doc" aria-hidden="true"><div class="ops-document"><span>INCOMING DOCUMENT</span><i></i><i></i><i></i><b>PDF</b><em></em></div><div class="ops-orb"><i></i><i></i><b>DP</b></div><div class="ops-extract"><span>EXTRACTED</span><strong>Fields validated</strong><small>confidence 98%</small></div><div class="ops-motion-arrow">→</div><div class="ops-action-stack"><span class="is-on">Validate</span><span>Update</span><span>Archive</span><span>Review</span></div></div><div class="ops-activity"><div class="ops-activity-head"><span>ACTIVITY</span><i></i></div><div class="ops-event is-hot"><span>DOC</span><b>File received</b><em>now</em></div><div class="ops-event"><span>DATA</span><b>Fields extracted</b><em>+2s</em></div><div class="ops-event"><span>RULES</span><b>Validation passed</b><em>+4s</em></div><div class="ops-event"><span>SYSTEM</span><b>Record updated</b><em>+6s</em></div></div></article></div><div class="ops-bottom-rail" aria-hidden="true"><span>INPUT</span><b>→</b><span>UNDERSTAND</span><b>→</b><span>RULES</span><b>→</b><span>ACTION</span><b>→</b><span>LOG</span><b>→</b><span>HUMAN WHEN NEEDED</span></div></div></div></section>`;

const founderProofSection=()=>`<section class="section founder-proof-section"><div class="shell founder-proof-grid"><div class="founder-proof-photo"><img src="/public/logos/customers/dustin-poole-about.png" width="1200" height="1200" alt="Dustin Poole, founder of Dream Protocol" loading="lazy"><div class="founder-photo-label"><span>FOUNDER / DREAM PROTOCOL</span><b>DUSTIN POOLE</b></div></div><div class="founder-proof-copy">${eyebrow('FOUNDER-LED / BUILT HANDS-ON')}<h2>AI built for the messy<br><em>real world of business.</em></h2><p class="founder-lead">Dream Protocol is founder-led by Dustin Poole and built around a simple standard: AI has to do useful work after the demo is over.</p><p>That means combining AI voice, business knowledge, APIs, automation, connected systems, guardrails, and human handoffs into something a customer or employee can actually use every day.</p><div class="founder-principles"><span>UNDERSTAND THE WORK</span><span>BUILD THE AI</span><span>CONNECT THE TOOLS</span><span>KEEP IT WORKING</span></div>${link('about','Meet Dream Protocol ↗','text-link')}</div></div></section>`;

