layout('services','AI Automation Services for Bay Area Businesses','Explore AI receptionists, lead response, scheduling and dispatch, workflow automation, document processing, knowledge agents, integrations, training, and custom AI builds.',`${crumbs([['services','Services']])}<section class="page-hero shell">${eyebrow('OUTCOMES FIRST. TECHNOLOGY SECOND.')}<h1>AI that actually<br><em>does the work.</em></h1><p>Answer calls. Respond to leads. Book work. Read documents. Find internal answers. Update the tools your team already uses. Start with the business pain, then give AI a useful job.</p><div class="actions"><a class="button" href="/#demo">Try the live receptionist demo ↗</a>${link('contact','Show us what wastes time ↗','text-link')}</div></section><section class="shell section compact">${heading('FLAGSHIP AUTOMATIONS','The work companies<br><em>want off their plate.</em>','Clear business outcomes, visible starting prices, and a defined path to launch.')}<div class="service-grid">${flagshipServices.map(serviceCard).join('')}</div></section><section class="section pale-section"><div class="shell">${heading('AI STRATEGY, INTEGRATIONS & SUPPORT','Build the intelligence.<br><em>Connect it to the business.</em>','Assessments, AI integrations, team training, managed AI operations, and custom builds extend the flagship automations or stand on their own.')}<div class="service-grid">${supportServices.map((s,i)=>serviceCard(s,i+flagshipServices.length)).join('')}</div></div></section>${stackSection()}${outcomesSection()}${processSection()}${cta()}`,{active:'services',crumbs:[['services','Services']]});

