layout('industries','AI for Every Kind of Bay Area Business','Explore practical AI workflows for Bay Area service teams, professional firms, accounting offices, retailers, property teams, and more.',`${crumbs([['industries','Industries']])}<section class="page-hero shell">${eyebrow('YOUR BUSINESS, YOUR WORKFLOW')}<h1>Your business has a rhythm.<br><em>AI should learn it.</em></h1><p>We build around your calls, customers, handoffs, tools, rules, and exceptions — not around a generic AI template.</p></section><section class="section shell compact">${industryCards()}<div class="wide-note"><h2>Your industry isn’t the limit.</h2><p>Startups, nonprofits, education teams, and other businesses are welcome. Bring a repeated task, a training need, or an idea.</p>${button('contact','Tell us about your business',true)}</div></section>${regional()}${cta()}`,{active:'industries',crumbs:[['industries','Industries']]});
for(const s of industries){layout(s.slug,s.title,s.description,`${crumbs([['industries','Industries'],[s.slug,s.name]])}<section class="page-hero shell">${eyebrow(s.name+' / BAY AREA')}<h1>${esc(s.headline).replace('\n','<br>')}</h1><p>${esc(s.need)}</p><div class="actions">${button('contact','Show us your workflow')}${link(s.primary,'Explore '+services.find(x=>x.slug===s.primary).name.toLowerCase()+' ↗','text-link')}</div></section><section class="section pale-section"><div class="shell">${heading('Where to begin','Make the next step clearer.')}<div class="three-grid">${s.steps.map(([t,p],i)=>`<article class="feature"><span class="step-number">0${i+1}</span><h3>${esc(t)}</h3><p>${esc(p)}</p></article>`).join('')}</div></div></section><section class="section shell"><div class="wide-note">${eyebrow('ILLUSTRATIVE EXAMPLE')}<h2>What it could look like.</h2><p>${esc(s.example)}</p><small>Example only. Your systems, requirements, and approved process shape the implementation.</small></div></section>${faq([s.faq,['Do you serve our part of the Bay Area?','We serve businesses across San Francisco, San Mateo, Santa Clara, Alameda, Contra Costa, Marin, Sonoma, Napa, and Solano counties. Start remotely; onsite delivery is quoted separately.']])}<section class="section shell">${heading('The services behind the workflow','Build my starting point.')}<div class="two-grid">${[s.primary,s.secondary].map(x=>services.find(v=>v.slug===x)).map(serviceCard).join('')}</div></section>${cta()}`,{active:'industries',crumbs:[['industries','Industries'],[s.slug,s.name]]});}

layout('bay-area-ai-services','AI Automation Services Across the San Francisco Bay Area','AI reception, lead response, scheduling, workflow automation, document processing, knowledge agents, integrations, training, and custom AI across the Bay Area. Explore services for your business and start a conversation.',`${crumbs([['bay-area-ai-services','Bay Area']])}<section class="page-hero shell">${eyebrow('ALL NINE COUNTIES. EVERY KIND OF BUSINESS.')}<h1>Bay Area speed.<br><em>AI that keeps up.</em></h1><p>AI systems for the businesses that keep the Bay Area moving. Faster response, cleaner handoffs, connected tools, and less repetitive work.</p><div class="actions">${button('contact','Talk about your business')}${link('services','Explore our services ↗','text-link')}</div></section>${regional()}<section class="section shell">${heading('Across the region','One connected Bay Area.','Start with a remote conversation. Onsite workshops and project work are quoted for your location and scope.')}<div class="region-grid">${[['San Francisco','San Francisco County','Customer inquiries, team training, and connected back-office work for businesses throughout the city.'],['The Peninsula','San Mateo County','Practical workflows for office teams, independent firms, and local service businesses.'],['South Bay','Santa Clara County','Training and integration projects for growing teams, shops, and service operations.'],['East Bay','Alameda & Contra Costa counties','Clearer intake and handoffs for teams working across communities and service areas.'],['North Bay','Marin, Sonoma, Napa & Solano counties','Business information, inquiry routing, and practical automation for local teams.']].map(([n,c,p])=>`<article class="region-card">${eyebrow(c)}<h3>${n}</h3><p>${p}</p></article>`).join('')}</div><p class="section-note">These are service areas. Project delivery and onsite availability are agreed during scoping.</p></section><section class="section pale-section"><div class="shell">${heading('Your business belongs here','A practical fit.<br>Across industries.')} ${industryCards()}</div></section>${faq([['Do you work with businesses outside technology?','Yes. We work across industries, including local shops, professional offices, contractors, hospitality, and property teams. The task and requirements determine the project.'],['Do we need to replace our software?','We start by reviewing the systems you already use. Integration depends on the APIs, permissions, and licenses available. We discuss any required changes before agreeing on scope.'],['Can our first step be a workshop?','Yes. The starting workshop is a two-hour remote session for up to five people at $750, with a prompt guide and one 30-minute follow-up. Onsite delivery and larger groups are quoted separately.']])}${cta()}`,{active:'bay-area-ai-services',crumbs:[['bay-area-ai-services','Bay Area']]});

layout('pricing','AI Automation Pricing & Starting Costs','See Dream Protocol starting prices for AI receptionists, lead response, scheduling, workflow automation, document processing, knowledge agents, integrations, training, managed operations, and custom AI.',`${crumbs([['pricing','Pricing']])}<section class="page-hero shell">${eyebrow('VISIBLE ENTRY POINTS. SCOPED DELIVERY.')}<h1>Start small.<br><em>Know what it costs.</em></h1><p>We publish useful starting prices where the work can be productized. Complex integrations and custom builds still get a real scope before you commit, not a made-up flat fee.</p></section><section class="section shell compact">${heading('FLAGSHIP AUTOMATIONS','Start with the outcome.','These are the services most businesses can recognize immediately. Pricing shown is the starting point for the published scope.')}<div class="pricing-grid">${flagshipServices.map(s=>`<article class="price-card">${eyebrow(s.tag)}<h2>${esc(s.name)}</h2><div class="price">${esc(s.price)}<small>${esc(s.unit)}</small></div><p>${esc(s.setup)}</p><ul class="check-list">${s.deliverables.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${button('contact?service='+encodeURIComponent(s.name),'Price my workflow')}${link(s.slug,'Explore the service ↗','text-link')}</article>`).join('')}</div></section><section class="section pale-section"><div class="shell">${heading('AI STRATEGY, INTEGRATIONS & SUPPORT','The work behind the AI.','AI integrations, assessments, training, managed AI operations, and custom builds vary by environment, so we publish the entry point and scope the rest.')}<div class="pricing-grid">${supportServices.map(s=>`<article class="price-card">${eyebrow(s.tag)}<h2>${esc(s.name)}</h2><div class="price">${esc(s.price)}<small>${esc(s.unit)}</small></div><p>${esc(s.setup)}</p><ul class="check-list">${s.deliverables.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${button('contact?service='+encodeURIComponent(s.name),'Discuss this service')}${link(s.slug,'Explore the service ↗','text-link')}</article>`).join('')}</div></div></section><section class="section shell compact"><p class="pricing-terms"><strong>How to read these prices:</strong> they are starting points for the published scope, not promises that every environment costs the same. Software licenses, model/voice/SMS usage, custom APIs, data cleanup, compliance work, larger teams, extra locations, and additional systems are quoted separately. We agree on the actual scope before work begins.</p></section>${outcomesSection()}${faq([['Why not publish one fixed price for everything?','Because a phone agent for one location and an integration across four legacy systems are not the same project. We publish useful starting points where the scope is repeatable and quote the variables that genuinely change the work.'],['Can we combine services?','Yes. A common build combines reception or lead response with scheduling, workflow automation, and systems integration. The proposal separates one-time setup, ongoing service, and third-party usage.'],['What does custom AI cost after discovery?','The full build depends on the users, systems, data, security, integrations, reliability, and support requirements. Paid discovery produces the scope and build proposal before you commit to the larger project.']])}${cta()}`,{crumbs:[['pricing','Pricing']]});

layout('about','About Dream Protocol','Meet Dream Protocol, a founder-led AI automation company building practical voice, workflow, integration, and business AI systems for Bay Area businesses.',`${crumbs([['about','About']])}<section class="page-hero shell about-hero">${eyebrow('FOUNDER-LED. SYSTEMS-MINDED. BUILT TO SHIP.')}<h1>Less AI theater.<br><em>More useful AI.</em></h1><p>Dream Protocol exists for the gap between an impressive AI demo and an AI system that can actually answer customers, use business knowledge, take approved actions, connect to real tools, and hand exceptions to people.</p></section>${founderProofSection()}<section class="section about-belief-section"><div class="shell about-belief-grid"><div>${eyebrow('WHY DREAM PROTOCOL EXISTS')}<h2>AI should do more of the work.<br><em>Not create more work.</em></h2></div><div><p>Businesses already have enough dashboards, inboxes, portals, and disconnected systems. Dream Protocol is about putting intelligence between those pieces so work moves without somebody copying, chasing, routing, or remembering every next step.</p><p>The goal is not to replace judgment. The goal is to remove repetition, make context easier to reach, and hand the unusual work to a person with the information they need.</p></div></div></section><section class="section shell about-principles-section">${heading('THE STANDARD','What we will not compromise on.','The product can evolve. The operating principles should not.')}<div class="about-principles-grid">${[['01','Show what is real','Live means live. Illustrative means illustrative. In development means exactly that.'],['02','Build around the business','The workflow, people, permissions, and existing systems come before the model choice.'],['03','Keep a human path','Exceptions, uncertainty, judgment, and sensitive situations need an explicit route back to a person.'],['04','Own the outcome','A deployment needs a measurable business result, monitoring, and a way to improve after launch.']].map(([n,h,p])=>`<article><span>${n}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section>${credibilitySection()}${stackSection()}${platformPreviewSection()}${processSection()}${cta()}`,{active:'about',crumbs:[['about','About']]});

layout('security','AI Security & Data Handling','How Dream Protocol approaches AI data boundaries, access, human review, vendor transparency, and regulated workflows for business automation.',`${crumbs([['security','Security & data']])}<section class="page-hero shell">${eyebrow('TRUST IS PART OF THE BUILD')}<h1>Useful AI.<br><em>Controlled access.</em></h1><p>AI automation only works when the business knows what information the system can use, what it can do, and where a person takes over. We design those boundaries before launch.</p></section><section class="section shell"><div class="three-grid"><article class="feature"><span class="step-number">01</span><h2>Use the minimum data needed</h2><p>Start from the information required to perform the approved task. The public website demo uses public website information only. Production data access is scoped separately.</p></article><article class="feature"><span class="step-number">02</span><h2>Control identity and permissions</h2><p>Review accounts, roles, credentials, source permissions, and the principle of least access. Integration scope depends on the controls available in the systems involved.</p></article><article class="feature"><span class="step-number">03</span><h2>Keep sensitive decisions human</h2><p>Define the situations where AI can draft, classify, route, or recommend versus the situations where a qualified person must review or decide.</p></article></div></section><section class="section pale-section"><div class="shell">${heading('REGULATED OR SENSITIVE WORK','Assess first.<br><em>Then automate.</em>','Healthcare, financial, legal, employee, and other sensitive-data workflows require an explicit review of systems, contracts, access, retention, and operational requirements before implementation.')}<div class="three-grid"><article class="feature"><span class="step-number">04</span><h3>Vendor transparency</h3><p>Identify the model, voice, messaging, hosting, and integration providers used in the proposed workflow and review the relevant data-handling settings before launch.</p></article><article class="feature"><span class="step-number">05</span><h3>Testing and exception paths</h3><p>Test routine cases, missing information, low-confidence output, connection failure, escalation, and human fallback before production use.</p></article><article class="feature"><span class="step-number">06</span><h3>Changes stay controlled</h3><p>Document the agreed workflow and test material changes before they go live. Managed AI operations is available when the system needs ongoing review and tuning.</p></article></div></div></section>${faq([['Do you claim every Dream Protocol workflow is HIPAA, SOC 2, or otherwise compliant?','No. Compliance depends on the complete architecture, vendors, contracts, data, configuration, and client responsibilities. Regulated workflows are assessed separately before implementation.'],['Does the website AI demo use private company data?','No. The public demo is designed around public information found on the website you provide. Do not enter private customer, patient, employee, financial, or confidential information into the public demo.'],['Can we require human approval before an AI action?','Yes. Approval, escalation, and exception steps can be built into a workflow when the business process requires them.']])}${cta()}`,{crumbs:[['security','Security & data']]});

layout('contact','Talk to Dream Protocol','Show Dream Protocol the business process you want to improve. Discuss AI reception, lead response, scheduling, workflow automation, document processing, integrations, knowledge agents, or custom AI.',`${crumbs([['contact','Contact']])}<section class="page-hero shell"><div class="contact-grid"><div>${eyebrow('YOUR NEXT CHAPTER STARTS HERE')}<h1>Show us what<br><em>wastes your time.</em></h1><p>Give us the ugly workflow, the missed calls, the copy-paste process, or the system that never talks to the other system.</p><a class="email-link" href="mailto:hello@dreamprotocol.ai">hello@dreamprotocol.ai ↗</a><p class="contact-trust">Have data or security questions? ${link('security','See how we approach AI security & data ↗')}</p><div class="contact-next"><h2>What happens next</h2><ol><li>You show us the friction.</li><li>We map the AI + systems path.</li><li>You get a clear scope before anything is built.</li></ol></div></div>${read('content/partials/contact.html')}</div></section>`,{crumbs:[['contact','Contact']]});

layout('resources','Practical AI Guides for Business','Guides to AI receptionists, team training, workflow automation, and systems integration. Practical reading for your next business decision.',`${crumbs([['resources','Resources']])}<section class="page-hero shell">${eyebrow('THE DREAM PROTOCOL RESOURCE LIBRARY')}<h1>Skip the AI hype.<br><em>Build what works.</em></h1><p>Straight answers for businesses deciding what to automate, what to connect, what AI can actually handle, and what should stay human.</p></section><section class="section shell compact"><div class="guide-grid">${published.map(guideCard).join('')}</div><div class="wide-note"><h2>Start with your question.</h2><p>Not sure which guide fits your situation? Tell us what you are trying to improve and we’ll help identify a practical starting point.</p>${button('contact','Ask about your workflow',true)}</div></section>${cta()}`,{active:'resources',crumbs:[['resources','Resources']]});
for(const g of published){
 const s=services.find(s=>s.slug===g.service);
 const slug='resources/'+g.slug;
 layout(slug,g.title,g.description,`${crumbs([['resources','Resources'],[slug,g.title]])}<article><header class="page-hero shell article-hero">${eyebrow(g.category+' / PRACTICAL GUIDE')}<h1>${esc(g.title)}</h1><p>${esc(g.description)}</p><div class="article-meta"><a href="/about/">Dream Protocol</a><span>Published <time datetime="${g.publishOn}">${g.publishOn}</time></span><span>${Math.max(3,Math.ceil(g.sections.map(x=>x.join(' ')).join(' ').split(/\s+/).length/200))} min read</span></div></header><div class="shell article-layout"><aside class="article-nav"><p class="eyebrow">IN THIS GUIDE</p>${g.sections.map(([h],i)=>`<a href="#section-${i+1}">${esc(h)}</a>`).join('')}${link(s.slug,'Explore '+s.name.toLowerCase()+' ↗','text-link')}</aside><div class="article-body"><div class="takeaway">${eyebrow('THE USEFUL TAKEAWAY')}<p>${esc(g.takeaway)}</p></div>${g.sections.map(([h,p],i)=>`<section id="section-${i+1}"><h2>${esc(h)}</h2><p>${esc(p)}</p>${g.sectionSources?.[i]?.length?`<p class="source-links">Sources: ${g.sectionSources[i].map(n=>`<a href="${esc(g.sources[n].url)}" rel="noopener noreferrer">${esc(g.sources[n].title)}</a>`).join(' · ')}</p>`:''}</section>`).join('')}<section class="article-checklist"><h2>Your next-step checklist</h2><ul class="check-list">${g.checklist.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><div class="article-source">${g.sources?`<p>Researched and checked with AI on <time datetime="${esc(g.generation.sourceCheckedOn)}">${esc(g.generation.sourceCheckedOn)}</time>. Source links appear beside the sections they support. Vendor features can change; confirm availability before implementation.</p>`:''}<p>About this guide: prepared for Dream Protocol’s resource library with AI assistance. It provides general planning guidance and uses Dream Protocol’s published service scope where pricing is discussed. It is not a client case study.</p>${link('pricing','Check current scope and pricing ↗')}</div></div></div></article><section class="section shell">${heading('Put the thinking to work','Explore your next step.')}<div class="two-grid">${serviceCard(s,0)}${published.find(x=>x.slug!==g.slug)?guideCard(published.find(x=>x.slug!==g.slug)):''}</div></section>${cta()}`,{active:'resources',article:true,crumbs:[['resources','Resources'],[slug,g.title]],schema:[{'@type':'Article',headline:g.title,description:g.description,datePublished:g.publishOn,dateModified:g.updatedOn||g.publishOn,author:{'@type':'Organization',name:'Dream Protocol',url:origin+'/about/'},publisher:{'@id':origin+'/#organization'},mainEntityOfPage:origin+href(slug),image:origin+'/public/dream-protocol-abstract.webp'}]});
}
// An old generated future page cannot leak into a date-controlled build.
for(const g of guides.filter(g=>!published.includes(g))){const f=path.join(root,'resources',g.slug,'index.html');if(fs.existsSync(f))fs.unlinkSync(f);}
layout('404','Page Not Found','Find your way back to Dream Protocol’s services and resources.',`<section class="page-hero shell">${eyebrow('404 / A DIFFERENT NEXT STEP')}<h1>Let’s get you<br><em>back on track.</em></h1><p>This page could not be found. Explore our services or tell us what you’re looking for.</p><div class="actions">${button('services','Explore services')}${button('contact','Talk to us',true)}</div></section>`,{noindex:true});
fs.renameSync(path.join(root,'404/index.html'),path.join(root,'404.html'));
const sitemap=`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${pages.map(p=>`  <url><loc>${esc(p.url)}</loc></url>`).join('\n')}\n</urlset>\n`;
write('sitemap.xml',sitemap);write('public/sitemap.xml',sitemap);
const robots='User-agent: *\nAllow: /\nSitemap: https://dreamprotocol.ai/sitemap.xml\n';write('robots.txt',robots);write('public/robots.txt',robots);
write('resources/feed.xml',`<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>Dream Protocol — Practical AI Guides</title><link>${origin}/resources/</link><description>Practical AI thinking for business.</description><language>en-us</language>${published.map(g=>`<item><title>${esc(g.title)}</title><link>${origin}/resources/${g.slug}/</link><guid isPermaLink="true">${origin}/resources/${g.slug}/</guid><pubDate>${new Date(g.publishOn+'T12:00:00Z').toUTCString()}</pubDate><description>${esc(g.description)}</description></item>`).join('')}</channel></rss>`);
write('content/published.json',JSON.stringify(published.map(g=>({slug:g.slug,publishOn:g.publishOn})),null,2)+'\n');
write('.nojekyll','');
console.log(`Built ${pages.length} indexable pages; ${published.length} guides published; ${guides.length-published.length} queued. Date: ${today}`);
